/* eslint-disable @typescript-eslint/no-unused-vars */
import { Container } from 'pixi.js';
import { IReelEvents, IReelEffects, IReelStopData, IServiceEvents, ISymbolEvents } from './../types/index';

export class GREvents {
    public readonly reelEvents: IReelEvents = {
        ON_BEGIN_SPIN_BEFORE_TICK: () => { return; },
        ON_REEL_SPINNING_BEFORE_TICK: () => { return; },
        ON_REEL_SPINNING_AFTER_TICK: () => { return; },
        ON_REEL_STOP: () => { return; },
        ON_SYMBOL_POSITION_SET_BEFORE_TICK: (symbol: Container) => { return symbol; },
        ON_SYMBOL_POSITION_SET_AFTER_TICK: (symbol: Container) => { return symbol; },
    };

    public readonly serviceEvents: IServiceEvents = {
        ON_SPIN_STATE_CHANGED: (states?: number[]) => { return; },
        ON_SCREENREELS_CHANGED: (reels?: number[][]) => { return; },
        ON_SPIN_SPEED_CHANGED: (spinSpeedValues?: number[]) => { return; },
        ON_SPIN_COMPLETE: () => { return; },
        ON_SEQUENCE_STEP: () => { return; },
    };

    public readonly reelEffects: IReelEffects = {
        REEL_STOP_EFFECT: (reelStopData: IReelStopData) => { return reelStopData; },
    };

    public readonly symbolEvents: ISymbolEvents = {
    };
}